import json
g=json.load(open('/mnt/c/Code/Github/Saranga/corpus/silver/pilot_v6/fable51_high/1306.2128v2.json'))
N={n['id']:n for n in g['nodes']}
src=json.load(open('facts.json'))['source']
import re
def key(s): return re.sub(r'\s+','',s)
K=key(src)
# check steps lie inside parent statement, are in order, and don't overlap
for pid in ['PP1.1','PP1.2','PP1.3','PP1.4']:
    P=key(N[pid]['statement']); pos=0
    def walk(parent, depth):
        global pos
        kids=[n for n in g['nodes'] if n.get('parent_id')==parent]
        kids.sort(key=lambda n:n['step_order'])
        for k in kids:
            ks=key(k['statement']); i=P.find(ks, pos)
            assert i>=0, (k['id'], 'not found in parent after pos')
            st=k['statement']
            print(f"{'  '*depth}{k['id']} o{k['step_order']} {k['subclass']:22s} | {st[:55]} ... {st[-30:]}")
            sub=[n for n in g['nodes'] if n.get('parent_id')==k['id']]
            if sub:
                save=pos; pos=i; walk(k['id'], depth+1); 
            pos=i+len(ks)
    pos=0; print("==",pid); walk(pid,1)
print("--- assumptions/conclusions")
for n in g['nodes']:
    for f in ('assumptions','conclusions','genus','differentia','definiendum'):
        if f in n:
            v=n[f] if isinstance(n[f],list) else [n[f]]
            for x in v:
                ok = key(x) in K
                print(n['id'], f, 'OK' if ok else 'NOT-VERBATIM', '|', x[:80])
